const transformed = students.map(student => {
  const cleanName = student.name
    .trim()
    .toLowerCase()
    .split(" ")
    .filter(word => word !== "")
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");

  const cleanEmail = student.email.trim().toLowerCase();

  let grade;

  if (student.score >= 90) {
    grade = "A";
  } else if (student.score >= 80) {
    grade = "B";
  } else if (student.score >= 70) {
    grade = "C";
  } else if (student.score >= 60) {
    grade = "D";
  } else {
    grade = "F";
  }

  return {
    name: cleanName,
    email: cleanEmail,
    score: Number(student.score),
    grade: grade
  };
});

const filtered = transformed.filter(student => {
  return student.grade === "A" || student.grade === "B";
});

return filtered.map(student => ({
  json: student
}));
